function EXTRA(R,ICON){
 /* hook: the same squeeze, cooled and insulated */
 const card=(x,y,title,col,insul,T,f)=>{let s=TD_box(0,0,240,370,{fill:'#FFFFFF',st:col,sw:4,r:18})+TD_T(120,40,title,{fs:26,fw:800,a:'middle',fill:col});
  if(insul){s+=`<rect x="60" y="96" width="136" height="232" rx="6" fill="#FFE8CC" stroke="${ORG}" stroke-width="3"/>`;for(let yy=106;yy<320;yy+=22)s+=TD_L(64,yy+14,192,yy-4,ORG,2)}
  else{for(let yy=150;yy<320;yy+=34){s+=TD_L(58,yy,40,yy,'#1C7ED6',5)+TD_L(198,yy,216,yy,'#1C7ED6',5)}}
  s+=TD_cyl(70,110,116,206,.22,{gas:insul?TD_HOT:TD_GAS,rod:24,bd:insul?ORG:'#1C7ED6'})+TD_arrow(128,56,128,84,TD_DARK,4,12);
  s+=TD_T(120,356,T,{fs:30,fw:800,a:'middle',fill:col});
  return `<g transform="translate(${x-120} ${y-185})">${s}</g>`};
 ICON.tdSlow=(x,y)=>card(x,y,'cooled','#1C7ED6',0,'300 K');
 ICON.tdFast=(x,y)=>card(x,y,'insulated',ORG,1,'689 K');
 /* recap pictures, each about 420 × 330 round its centre */
 ICON.tdPair=(x,y)=>`<g transform="translate(${x-210} ${y-160})">${TD_tank(10,70,170,190)}${TD_T(95,175,'c<tspan baseline-shift="sub" font-size="70%">v</tspan>',{fs:44,fw:800,a:'middle',fill:BLU})}${TD_T(95,40,'V fixed',{fs:24,fw:800,a:'middle',fill:TD_GREY})}
  ${TD_cyl(240,90,170,180,.6,{rod:40})}${TD_T(325,220,'c<tspan baseline-shift="sub" font-size="70%">p</tspan>',{fs:44,fw:800,a:'middle',fill:ORG})}${TD_T(325,30,'p fixed',{fs:24,fw:800,a:'middle',fill:TD_GREY})}</g>`;
 ICON.tdFamily=(x,y)=>`<g transform="translate(${x-210} ${y-160})">${TD_family(50,300,330,270,{fs:24,short:1,lx:250})}</g>`;
 ICON.tdBal=(x,y)=>{const k=1.1,bw=110,base=300;
  const bar=(bx,v,col,lab,val,top)=>`<rect x="${bx}" y="${(top??base-v*k).toFixed(1)}" width="${bw}" height="${(v*k).toFixed(1)}" rx="6" fill="${col}" fill-opacity=".85"/>`+TD_T(bx+bw/2,(top??base-v*k)-12,val,{fs:24,fw:800,a:'middle',fill:col})+TD_T(bx+bw/2,base+32,lab,{fs:24,fw:800,a:'middle',fill:TD_DARK});
  return `<g transform="translate(${x-210} ${y-170})">${bar(20,248.6,GRN,'W in','248.6')}${bar(160,186.6,BLU,'ΔU','186.6')}${bar(300,62.0,ORG,'Q out','62.0',base-248.6*k)}
   ${TD_L(10,base,420,base,TD_DARK,3)}${TD_L(130,base-248.6*k,300,base-248.6*k,TD_GREY,2,'stroke-dasharray="6 5"')}</g>`};
}
